// Vulnérable à l'injection SQL :
const query = `SELECT * FROM users WHERE email = '${email}'`;

// Protégé avec une requête préparée (paramétrée) :
await prisma.user.findUnique({ where: { email } }); // Prisma échappe automatiquement

// Autre piège : comparer un mot de passe en clair, même avec une requête sécurisée :
const valide = password === user.password; // FAUX : le mot de passe ne doit jamais être stocké en clair

// Bonne pratique : comparer le hash bcrypt
const valide2 = await bcrypt.compare(password, user.passwordHash); // vérifie sans jamais exposer le mot de passe en clair

// Violation du principe de responsabilité unique :
class Facture {
  calculerTotal() { /* ... */ }
  sauvegarderEnBDD() { /* ... */ } // ne devrait pas être ici
  envoyerParEmail() { /* ... */ } // ni ici
}
// Mieux : séparer en Facture, FactureRepository, FactureMailer

// Exemple de test unitaire (style Jest/Vitest)
test('additionne deux nombres', () => {
  expect(additionner(2, 3)).toBe(5);
});

test('lève une erreur si division par zéro', () => {
  expect(() => diviser(4, 0)).toThrow();
});

test('appelle le callback une seule fois', () => {
  const spy = vi.fn();
  appelerCallback(spy);
  expect(spy).toHaveBeenCalledTimes(1); // vérifie qu'aucun appel superflu n'a eu lieu
});

